import json
import re
import xml.etree.ElementTree as ET
from datetime import datetime, timedelta, timezone

NS = {
    "torznab": "http://torznab.com/schemas/2015/feed",
    "newznab": "http://www.newznab.com/DTD/2010/feeds/attributes/",
}

MONTHS = {
    "Jan": 1, "Feb": 2, "Mar": 3, "Apr": 4, "May": 5, "Jun": 6,
    "Jul": 7, "Aug": 8, "Sep": 9, "Oct": 10, "Nov": 11, "Dec": 12,
}

GROUP_RE = re.compile(r"^\s*[\[【]([^\]】]{1,32})[\]】]")
RES_RE = re.compile(r"(2160p|1080p|720p|480p|4K)", re.I)
FMT_RE = re.compile(r"\b(MKV|MP4|AVI|WEBM)\b", re.I)
SUB_RE = re.compile(r"(简繁日内封|简繁内封|简日内封|简繁日|简日|繁日|简繁|简体|繁体|内封|内嵌|外挂)")


def text(item, tag):
    """Read a direct child element's text."""
    child = item.find(tag)
    if child is None or child.text is None:
        return ""
    return child.text.strip()


def attrs(item):
    """Collect torznab attributes into a plain dict."""
    result = {}
    for node in item.findall("torznab:attr", NS):
        name = node.get("name")
        if name:
            result[name] = node.get("value", "")
    return result


def human_size(value):
    """Format a byte count as a human readable size."""
    try:
        size = float(value)
    except (TypeError, ValueError):
        return ""
    for unit in ("B", "KB", "MB", "GB", "TB"):
        if size < 1024 or unit == "TB":
            return f"{int(size)} B" if unit == "B" else f"{size:.2f} {unit}"
        size /= 1024.0
    return ""


def parse_pubdate(raw):
    """Parse an RFC 822 pubDate without the email module (banned in sandbox)."""
    try:
        part = raw.split(",", 1)[1].strip() if "," in raw else raw.strip()
        day, month, year, clock, zone = part.split()
        hour, minute, second = clock.split(":")
        sign = 1 if zone[0] == "+" else -1
        offset = sign * (int(zone[1:3]) * 60 + int(zone[3:5]))
        moment = datetime(
            int(year), MONTHS[month], int(day), int(hour), int(minute), int(second),
            tzinfo=timezone(timedelta(minutes=offset)),
        )
        return moment.timestamp()
    except (IndexError, KeyError, TypeError, ValueError):
        return 0.0


def describe(title):
    """Extract group, resolution, subtitle and format from the release title."""
    group = ""
    if match := GROUP_RE.match(title):
        group = match.group(1).strip()
    tags = []
    if match := RES_RE.search(title):
        tags.append(match.group(1).upper())
    if match := SUB_RE.search(title):
        tags.append(match.group(1))
    if match := FMT_RE.search(title):
        tags.append(match.group(1).upper())
    return group, " \u00b7 ".join(dict.fromkeys(tags))


def magnet(info_hash, title):
    """Build a magnet URI from an infohash."""
    return f"magnet:?xt=urn:btih:{info_hash}&dn={title}" if info_hash else ""


def execute(node_id, node_data, context):
    """Parse the AniBT Torznab search response into search results."""
    raw = context.get("response") or ""
    try:
        root = ET.fromstring(raw)
    except ET.ParseError as exc:
        raise ValueError("AniBT did not return valid Torznab XML") from exc

    items = []
    for item in root.iter("item"):
        title = text(item, "title")
        if not title:
            continue
        extra = attrs(item)
        info_hash = extra.get("infohash", "")
        try:
            size_value = float(extra.get("size") or 0)
        except ValueError:
            size_value = 0.0
        group, misc = describe(title)
        items.append({
            "id": text(item, "guid"),
            "title": title,
            "link": magnet(info_hash, title) or text(item, "link"),
            "size": human_size(size_value),
            "misc": misc,
            "category": "番剧",
            "uploader": group or "AniBT",
            "uploaded_at": text(item, "pubDate"),
        })

    context["search_result"] = json.dumps({
        "total": len(items),
        "totalPages": None,
        "page": int(context.get("page_num") or 1),
        "items": items,
    })
